-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_set_translations AS SELECT set_translations.id AS id, set_translations.language AS language, set_translations.setCode AS setCode, set_translations.translation AS translation, setCode.id AS setCode_id, setCode.baseSetSize AS baseSetSize, setCode.block AS block, setCode.booster AS booster, setCode.isFoilOnly AS isFoilOnly, setCode.isForeignOnly AS isForeignOnly, setCode.isNonFoilOnly AS isNonFoilOnly, setCode.isOnlineOnly AS isOnlineOnly, setCode.isPartialPreview AS isPartialPreview, setCode.keyruneCode AS keyruneCode, setCode.mcmId AS mcmId, setCode.mcmIdExtras AS mcmIdExtras, setCode.mcmName AS mcmName, setCode.mtgoCode AS mtgoCode, setCode.name AS name, setCode.parentCode AS parentCode, setCode.releaseDate AS releaseDate, setCode.tcgplayerGroupId AS tcgplayerGroupId, setCode.totalSetSize AS totalSetSize, setCode.type AS type FROM set_translations LEFT JOIN sets AS setCode ON set_translations.setCode = setCode.code;
